use super::*;
use crate::snapshot::state::{StateZone,ModelGeometryState};
#[path="../../../../📸️snapshot/🧳️state/🧪️tests/🧰️helpers/🦀️.rs"]mod helpers;
use helpers::{corpus,receive,source,grant,observe,drain,central_fragment,project_record,denied_axes};
struct ZoneName;
impl TextRowPath for ZoneName{
 type Row=StateZone;type Branch=ModelGeometryState;type Output=crate::row::DirectBranchOutput<Self::Branch>;const UNIQUE:bool=true;
 fn rows(o:RetainedCloneRef<'_,EnergyModelSnapshot>)->RetainedCloneRef<'_,PersistentList<Self::Row>>{o.project(0,|s|&s.model.geometry.get().zones)}
 fn branch(o:RetainedCloneRef<'_,EnergyModelSnapshot>)->RetainedCloneRef<'_,Self::Branch>{o.project(1,|s|s.model.geometry.get())}
 fn rows_mut(b:&mut Self::Branch)->&mut PersistentList<Self::Row>{&mut b.zones}
 fn read(r:&Self::Row)->&SealedShared<String>{&r.name}
 fn select(r:&mut Self::Row)->&mut SealedShared<String>{&mut r.name}
 fn output()->Self::Output{crate::row::DirectBranchOutput::new(|branch|{let mut diff=EnergyModelDiff::default();diff.model.geometry=Some(branch);diff})}
}
#[test]
fn native_row_names_preserve_sparse_paths_original_inverse_and_every_cancelled_prefix(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();assert!(size_of::<TextRowPreparation<ZoneName>>()<=4096);
 for case in law["cases"].as_array().unwrap(){let mut value:serde_json::Value=serde_json::from_str(include_str!("../../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();value=value["document"].take();value["model"]=corpus()["model"].clone();value["model"]["zones"][0]["id"]=1.into();value["model"]["zones"][0]["name"]=case["before"].clone();if let Some(other)=case.get("other"){let mut row=value["model"]["zones"][0].clone();row["id"]=2.into();row["name"]=other.clone();value["model"]["zones"].as_array_mut().unwrap().push(row);}let original=source(receive::<EnergyModelSnapshot>(&value));let input=source(case["value"].as_str().unwrap().to_owned());let key=source(case["id"].as_u64().unwrap()as u32);
  for cut in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize))){let mut owner=TextRowPreparation::<ZoneName>::new();let mut turns=0;while !owner.ready()&&cut.is_none_or(|cut|turns<cut){let d=owner.demand(input.borrow(),key.borrow(),original.borrow(),4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.advance(input.borrow(),key.borrow(),original.borrow(),4096,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.demand(input.borrow(),key.borrow(),original.borrow(),4096).unwrap(),d);}let(s,h)=observe(||owner.advance(input.borrow(),key.borrow(),original.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));turns+=1;assert!(turns<10000);}
   if cut.is_none(){assert_eq!(owner.outcome().unwrap().as_str(),case["outcome"].as_str().unwrap());if owner.outcome()==Some(TextOutcome::Changed){let(diff,_)=owner.take(grant(owner.take_demand().unwrap())).unwrap().unwrap();let diff=source(diff);let mut post=project_record(original.borrow());assert!(central_fragment(&diff,original.borrow(),&mut post));assert_eq!(post.model.geometry.get().zones.get(0).unwrap().name.get(),case["after"].as_str().unwrap());assert_eq!(post.model.materials.identity(),original.borrow().get().model.materials.identity());assert_eq!(post.model.geometry.get().spaces.get(0).map(|row|row as *const _),original.borrow().get().model.geometry.get().spaces.get(0).map(|row|row as *const _));for _ in 0..10000{if owner.inverse_ready(){break;}let g=grant(owner.inverse_demand(4096).unwrap());let(s,h)=observe(||owner.inverse(4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.inverse_ready());let(inverse,_)=owner.take_inverse(grant(owner.take_inverse_demand().unwrap())).unwrap().unwrap();assert_eq!(inverse,case["before"].as_str().unwrap());drain(inverse);drain(post);drain(diff);}}
   owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break;}let d=owner.close_demand(4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.close_step(denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.close_demand(4096).unwrap(),d);}let(s,h)=observe(||owner.close_step(g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));assert_eq!(original.borrow().get().model.geometry.get().zones.get(0).unwrap().name.get(),case["before"].as_str().unwrap());
  }drain(key);drain(input);drain(original);
 }
}

#[derive(Debug,semio_framework_value::ToValue,semio_framework_value::FromValue,semio_framework_value::RetireOwned)]
struct NameOperation{id:u32,value:String}
impl protocol::Mutation<EnergyModelSnapshot> for NameOperation{type Diff=EnergyModelDiff;const DESCRIPTORS:&'static[protocol::MutationLeafDescriptor]=&[];fn descriptor(&self)->&'static protocol::MutationLeafDescriptor{panic!("fixture exercises only retained semantic ports")}}
impl super::TextLeafSpec<NameOperation,NameOperation> for ZoneName{
 const DUPLICATE:protocol::mutation::retained::RetainedDiagnosticSpec=protocol::mutation::retained::RetainedDiagnosticSpec{level:store::__diagnostic::Severity::Fatal,code:"mutation.duplicate-id",message:"Another zone already has this name."};
 const INVALID:protocol::mutation::retained::RetainedDiagnosticSpec=protocol::mutation::retained::RetainedDiagnosticSpec{level:store::__diagnostic::Severity::Fatal,code:"mutation.invariant",message:"A zone volume must be positive and finite."};
 const MISSING:protocol::mutation::retained::RetainedDiagnosticSpec=protocol::mutation::retained::RetainedDiagnosticSpec{level:store::__diagnostic::Severity::Error,code:"mutation.target-missing",message:"The addressed zone does not exist."};
 const UNCHANGED:protocol::mutation::retained::RetainedDiagnosticSpec=protocol::mutation::retained::RetainedDiagnosticSpec{level:store::__diagnostic::Severity::Warning,code:"mutation.no-op",message:"The zone already has this volume."};
 fn input(payload:RetainedCloneRef<'_,NameOperation>)->RetainedCloneRef<'_,String>{payload.project(0,|p|&p.value)}
 fn key(payload:RetainedCloneRef<'_,NameOperation>)->RetainedCloneRef<'_,u32>{payload.project(1,|p|&p.id)}
 fn inverse(payload:RetainedCloneRef<'_,NameOperation>,value:String)->NameOperation{NameOperation{id:payload.get().id,value}}
}
#[test]
fn shared_native_text_leaf_preserves_diagnostics_and_original_text_inverse_custody(){
 use super::TextLeafPreparation;
 use protocol::mutation::retained::{RetainedMutationLeafPreparation,RetainedMutationAdvance,RetainedMutationDecision,RetainedMutationCloseContext};
 type Owner=TextLeafPreparation<NameOperation,NameOperation,ZoneName>;
 assert!(size_of::<Owner>()<=4096);
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
 for case in law["cases"].as_array().unwrap().iter(){
  let mut document:serde_json::Value=serde_json::from_str(include_str!("../../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();document=document["document"].take();document["model"]=corpus()["model"].clone();document["model"]["zones"][0]["id"]=1.into();document["model"]["zones"][0]["name"]=case["before"].clone();if let Some(other)=case.get("other"){let mut row=document["model"]["zones"][0].clone();row["id"]=2.into();row["name"]=other.clone();document["model"]["zones"].as_array_mut().unwrap().push(row);}let original=source(receive::<EnergyModelSnapshot>(&document));let payload=source(NameOperation{id:case["id"].as_u64().unwrap()as u32,value:case["value"].as_str().unwrap().to_owned()});
  for cutoff in std::iter::once(None).chain((0..200).map(Some)){
   let mut owner=Owner::new();let mut ready=false;for _ in 0..cutoff.unwrap_or(10000){let d=owner.decision_demand(payload.borrow(),original.borrow(),4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.decide(payload.borrow(),original.borrow(),4096,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.decision_demand(payload.borrow(),original.borrow(),4096).unwrap(),d);}let(s,h)=observe(||owner.decide(payload.borrow(),original.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,RetainedMutationAdvance::Ready(_)){ready=true;break;}}
   let mut diff=None;let mut inverse=None;if ready{match owner.take_decision(){RetainedMutationDecision::Refused(messages)=>{assert!(case["outcome"]=="invalid"||case["outcome"]=="missing"||case["outcome"]=="duplicate");assert_eq!(messages[0].target,[case["id"].as_u64().unwrap().to_string()]);close_messages(messages);},RetainedMutationDecision::Admitted(value,messages)=>{assert!(case["outcome"]=="changed"||case["outcome"]=="no-op");assert_eq!(messages.len(),usize::from(case["outcome"]=="no-op"));close_messages(messages);let value=source(value);for _ in 0..cutoff.unwrap_or(10000){let g=grant(owner.inverse_demand(payload.borrow(),original.borrow(),value.borrow(),4096).unwrap());let(s,h)=observe(||owner.inverse(payload.borrow(),original.borrow(),value.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,RetainedMutationAdvance::Ready(_)){if cutoff.is_none(){let rows=owner.take_inverse();assert_eq!(rows.len(),usize::from(case["outcome"]=="changed"));if let Some(row)=rows.first(){assert_eq!(row.id,payload.borrow().get().id);assert_eq!(row.value,case["before"].as_str().unwrap());}inverse=Some(rows);}break;}}diff=Some(value);}}}else{assert!(cutoff.is_some());}
   let factory=semio_framework_value::factory::OwnedValueRetirementFactory::<NameOperation>::default();let context=RetainedMutationCloseContext{mutations:&factory};owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break;}let d=owner.close_demand(context,4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.close_step(context,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.close_demand(context,4096).unwrap(),d);}let(s,h)=observe(||owner.close_step(context,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));if let Some(diff)=diff{drain(diff);}if let Some(inverse)=inverse{drain(inverse);}
  }drain(payload);drain(original);
 }
}
fn close_messages(messages:Vec<protocol::MutationMessage>){let mut owner=protocol::MutationMessageLedgerRetirement::new(String::new(),messages);for _ in 0..10000{if owner.terminal_is_empty(){return;}let d=semio_framework_value::RetirementDemand{copy_bytes:owner.next_copy_byte_demand(),capacity_bytes:owner.next_capacity_byte_demand(4096).unwrap(),release_bytes:owner.next_release_byte_demand().unwrap(),depth:owner.next_depth_demand().unwrap()};let g=grant(d);let(s,h)=observe(||owner.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}panic!("native scalar diagnostic close stalled");}
